    if (!/^[a-z]{2}$/.test(iso2)) {
      return `<span class="wc-country-flag is-placeholder" aria-hidden="true" data-country-flag-state="missing" data-country-iso3="${esc(iso3)}"></span>`;
    }
    return `<span class="wc-country-flag" aria-hidden="true" data-country-flag-state="svg" data-country-iso3="${esc(iso3)}"><span class="wc-country-native">${esc(nativeFlag(iso2))}</span><img class="wc-country-flag-image country-flag-image" src="assets/vendor/flags/4x3/${esc(iso2)}.svg" alt="" loading="lazy" /></span>`;
