  function evidenceMeta(evidenceClass) {
    return evidenceLabels[evidenceClass] || {
      ru: evidenceClass || "не указано",
      en: evidenceClass || "not specified",
      className: "wc-evidence-missing",
    };
  }

  function sourceSummary(source) {
    if (!source || Object.keys(source).length === 0) return t("noSource");
    return [
      sourceLabel(pick(source.source_title) || source.source_key),
      sourcePeriodLabel(pick(source.source_period)),
      pick(source.unit),
      pick(source.evidence_class),
    ].filter(Boolean).join(" · ") || t("noSource");
  }

